results.query:
SELECT ?date WHERE {
  dbr:Rachel_Stevens dbo:birthDate ?date .
  ?artist dbo:birthDate ?date .
  FILTER(?artist != dbr:Rachel_Stevens)
}

SELECT ?airline ?airlineCount WHERE {
  ?program dbo:frequentFlyerProgramFor ?airline .
  ?airline a dbo:Airline .
} GROUP BY ?program ORDER BY DESC(?airlineCount) LIMIT 1

SELECT ?country WHERE {
  ?country dbo:governmentType dbr:Constitutional_monarchy .
  ?country dbo:sovereignCountry dbr:Europe .
}

SELECT ?skateboarder WHERE {
  ?skateboarder dbo:profession dbr:Skateboarding .
  ?skateboarder dbo:nationality dbr:Sweden .
}

SELECT ?state WHERE {
  ?state a dbo:Settlement .
  ?state dbo:currentStatus dbr:Admitted_State_of_the_United_States .
  ?state dbo:dateLastUpdated ?date .
} ORDER BY DESC(?date) LIMIT 1

SELECT ?writer WHERE {
  ?writer dbo:nobelLaureates dbr:Nobel_Prize_in_Literature .
  ?writer a dbo:Writer .
}

SELECT ?name WHERE {
  dbr:Lovesick dbo:starring ?actor .
  ?actor a dbo:Actor .
  ?actor rdfs:label ?name .
  FILTER(lang(?name) = "en")
}

SELECT (COUNT(DISTINCT ?scientist) AS ?count) WHERE {
  ?scientist dbo:alumni dbr:Ivy_League .
  ?scientist a dbo:Scientist .
}

SELECT ?surfer WHERE {
  ?surfer a dbo:Surfer .
  ?surfer dbo:birthPlace dbr:Australia .
}

SELECT ?party WHERE {
  ?party a dbo:PoliticalParty ;
           dbo:language dbr:Dutch_language .
}

SELECT (COUNT(DISTINCT ?year) AS ?count) WHERE {
  dbr:Ford_Model_T dbo:modelStartYear ?startYear .
  dbr:Ford_Model_T dbo:modelEndYear ?endYear .
  ?year a dbo:Year ;
         dbo:year ?yearNum .
  FILTER(?yearNum >= ?startYear && ?yearNum <= ?endYear)
}

SELECT ?city WHERE {
  ?city a dbo:City ;
         dbo:country dbr:Germany ;
         dbo:populationTotal ?population .
  FILTER(?population > 250000)
}

SELECT ?volcano WHERE {
  ?volcano a dbo:Volcano ;
            dbo:highestMountain dbr:Africa .
}
ORDER BY DESC(?highestAltitude) LIMIT 1

SELECT ?poet (COUNT(DISTINCT ?book) AS ?count) WHERE {
  ?poet dbo:notableWork ?work .
  ?work a dbo:Book ;
         dbo:author ?poet .
} GROUP BY ?poet ORDER BY DESC(?count) LIMIT 1

